/** 본문 Markdown의 한 덩어리. 읽기 본문이 그리는 만큼만 다룬다(소제목 · 문단 · 목록 · 인용 · 코드 블록). */
export type MarkdownBlock =
  | { kind: "heading"; level: 2 | 3; text: string }
  | { kind: "paragraph"; text: string }
  | { kind: "list"; isOrdered: boolean; items: string[] }
  | { kind: "quote"; text: string }
  | { kind: "code"; text: string }

const FENCE = /^```/
const HEADING = /^(#{1,3})\s+(.*)$/
const ITEM = /^\s*(?:[-*]|\d+\.)\s+/
const QUOTE = /^>\s?/
const startsBlock = (line: string) => FENCE.test(line) || HEADING.test(line) || ITEM.test(line) || QUOTE.test(line)

/** 빈 줄로 나뉜 Markdown을 덩어리로 읽는다. # · ## 는 2단계, ### 는 3단계 소제목이다. */
export function parseMarkdown(source: string): MarkdownBlock[] {
  const lines = source.replace(/\r\n?/g, "\n").split("\n")
  const blocks: MarkdownBlock[] = []
  let index = 0
  const takeWhile = (test: (line: string) => boolean) => {
    const taken: string[] = []
    while (index < lines.length && test(lines[index])) taken.push(lines[index++])
    return taken
  }
  while (index < lines.length) {
    const line = lines[index]
    if (!line.trim()) {
      index++
    } else if (FENCE.test(line)) {
      index++
      blocks.push({ kind: "code", text: takeWhile(each => !FENCE.test(each)).join("\n") })
      index++
    } else if (HEADING.test(line)) {
      const [, marks, text] = HEADING.exec(line)!
      blocks.push({ kind: "heading", level: marks.length === 3 ? 3 : 2, text })
      index++
    } else if (ITEM.test(line)) {
      const isOrdered = /^\s*\d+\./.test(line)
      blocks.push({ kind: "list", isOrdered, items: takeWhile(each => ITEM.test(each)).map(each => each.replace(ITEM, "")) })
    } else if (QUOTE.test(line)) {
      blocks.push({ kind: "quote", text: takeWhile(each => QUOTE.test(each)).map(each => each.replace(QUOTE, "")).join(" ") })
    } else {
      blocks.push({ kind: "paragraph", text: takeWhile(each => Boolean(each.trim()) && !startsBlock(each)).join(" ") })
    }
  }
  return blocks
}

/** 글 속 표시: `코드`와 **굵게**. 나머지는 글자 그대로다. */
export type InlinePart = { kind: "text" | "code" | "strong"; text: string }

export function parseInline(text: string): InlinePart[] {
  return text.split(/(`[^`]+`|\*\*[^*]+\*\*)/).filter(Boolean).map(part =>
    part.startsWith("`") ? { kind: "code", text: part.slice(1, -1) }
      : part.startsWith("**") ? { kind: "strong", text: part.slice(2, -2) }
        : { kind: "text", text: part })
}

import { useMemo } from "react"
import { parseInline, parseMarkdown, type MarkdownBlock } from "../model/markdown"

/** 글 속 코드는 바탕 없이 옅은 밑줄과 조금 옅은 고정폭 글자(호호코워크 읽기 본문). */
function Inline({ text }: { text: string }) {
  return parseInline(text).map((part, index) =>
    part.kind === "code" ? (
      <code key={index} className="font-mono text-[0.9em] text-foreground/80 underline decoration-foreground/40 decoration-1 underline-offset-[0.32em]">{part.text}</code>
    ) : part.kind === "strong" ? (
      <strong key={index} className="font-semibold">{part.text}</strong>
    ) : (
      part.text
    ))
}

function Block({ block }: { block: MarkdownBlock }) {
  switch (block.kind) {
    case "heading":
      return block.level === 2
        ? <h2 className="mt-4 text-[1.625rem] leading-[1.35] font-bold tracking-[-0.02em]"><Inline text={block.text} /></h2>
        : <h3 className="mt-2 text-xl leading-[1.4] font-semibold"><Inline text={block.text} /></h3>
    case "list": {
      const List = block.isOrdered ? "ol" : "ul"
      return (
        <List className={block.isOrdered ? "flex list-decimal flex-col gap-1 pl-6" : "flex list-disc flex-col gap-1 pl-6"}>
          {block.items.map((item, index) => <li key={index} className="pl-1"><Inline text={item} /></li>)}
        </List>
      )
    }
    case "quote":
      return <blockquote className="border-l-2 border-input pl-4 text-muted-foreground"><Inline text={block.text} /></blockquote>
    case "code":
      return (
        <pre className="overflow-x-auto rounded-lg border bg-muted px-4 py-3 font-mono text-[0.8125rem] leading-relaxed">
          <code>{block.text}</code>
        </pre>
      )
    case "paragraph":
      return <p><Inline text={block.text} /></p>
  }
}

/**
 * 읽기 본문(호호코워크 MarkdownBody): 16px · 줄 높이 1.7, 문단 사이 한 줄. 긴 낱말과 주소는 칸을 넓히지 않고 접는다.
 * 소제목 · 목록 · 인용 · 코드 블록과 글 속 코드 · 굵게만 그린다.
 */
export function MarkdownBody({ source }: { source: string }) {
  const blocks = useMemo(() => parseMarkdown(source), [source])
  return (
    <div className="flex min-w-0 flex-col gap-4 text-[1rem]/[1.7] wrap-anywhere">
      {blocks.map((block, index) => <Block key={index} block={block} />)}
    </div>
  )
}

import type { ReactNode } from "react"
import { cn } from "@/shared/lib/utils"

/** 상세 속성의 한 묶음(속성 · 라벨 · 프로젝트 …): 넓은 옆 칸에서 이 이름 아래에 알약이 줄로 선다. */
export type DetailSection = { title: string; items: ReactNode }

type DetailLayoutProps = {
  /** 화면 읽기용 이름: "WEB-14 업무 제목". */
  label: string
  /** 제목 위 소속 줄: 프로젝트 · 키 · 상위 항목. */
  head?: ReactNode
  title: string
  /** 속성 알약 묶음. 한 번만 쓰고, 자리와 모양은 이 틀이 정한다. */
  sections: DetailSection[]
  /** 본문. */
  children: ReactNode
  /** 본문 뒤: 하위 항목 · 활동. */
  after?: ReactNode
}

/*
 * 넓은 상세(자기 폭 60rem 이상, 컨테이너 쿼리): 45rem 읽기 단과 오른쪽 16rem 속성 칸을 페이지 가운데에 둔다.
 * Tailwind는 완성된 클래스 이름만 읽으므로 @min-[60rem]/detail: 접두를 그대로 적는다.
 */
const GRID = [
  "mx-auto grid max-w-180 grid-cols-1 gap-y-4 px-4 pt-5 pb-10",
  "@min-[60rem]/detail:max-w-[calc(45rem+16rem+3rem+4rem)] @min-[60rem]/detail:grid-cols-[minmax(0,45rem)_16rem]",
  "@min-[60rem]/detail:grid-rows-[auto_auto_1fr] @min-[60rem]/detail:gap-x-12 @min-[60rem]/detail:px-8 @min-[60rem]/detail:pt-8 @min-[60rem]/detail:pb-12",
].join(" ")
const MAIN = "min-w-0 @min-[60rem]/detail:col-start-1"
const SIDE = [
  "flex min-w-0 flex-wrap gap-1.5",
  "@min-[60rem]/detail:sticky @min-[60rem]/detail:top-6 @min-[60rem]/detail:col-start-2 @min-[60rem]/detail:row-span-3 @min-[60rem]/detail:row-start-1",
  "@min-[60rem]/detail:flex-col @min-[60rem]/detail:flex-nowrap @min-[60rem]/detail:gap-6 @min-[60rem]/detail:self-start",
].join(" ")
const GROUP = "contents @min-[60rem]/detail:flex @min-[60rem]/detail:flex-col @min-[60rem]/detail:items-start @min-[60rem]/detail:gap-0.5"
const GROUP_TITLE = "hidden px-2 pb-1 text-xs font-medium text-muted-foreground @min-[60rem]/detail:block"

/** 상세의 제목. 본문 안의 어떤 소제목(26px)보다 크다. */
function DetailTitle({ children }: { children: string }) {
  return <h1 className="text-[2rem] leading-[1.3] font-bold tracking-[-0.025em] text-balance break-keep">{children}</h1>
}

/** 속성 묶음. 좁으면 묶음 이름 없이 알약이 한 줄로 이어지고(contents), 넓은 옆 칸에서는 이름 아래 세로 줄이 된다. */
function DetailProperties({ sections }: { sections: DetailSection[] }) {
  return (
    <aside aria-label="속성" className={SIDE}>
      {sections.map(section => (
        <section key={section.title} aria-label={section.title} className={GROUP}>
          <h2 className={GROUP_TITLE}>{section.title}</h2>
          {section.items}
        </section>
      ))}
    </aside>
  )
}

/**
 * 본문이 있는 것의 상세(호호코워크 DetailLayout, Linear 이슈 모양): 업무 · 일정 · 회의록 · 공지사항이 같이 쓴다.
 * 위에서 아래로 소속 줄, 제목, 본문과 그 뒤(하위 항목 · 활동)를 45rem 읽기 단에 둔다. 너비는 창이 아니라 자기 폭(컨테이너 쿼리)이다.
 * - 자기 폭이 60rem 이상이면 속성은 오른쪽 16rem 칸에 묶음 이름 아래 줄로 붙어 따라온다.
 * - 좁으면(휴대폰 포함) 제목과 본문 사이에 한 줄 알약으로 놓이고, 넘치면 다음 줄로 넘긴다. 스크롤은 페이지 본문이 맡는다.
 * 페이지의 점 무늬를 자기 바탕으로 가린다(상세 면에는 무늬가 없다).
 */
export function DetailLayout({ label, head, title, sections, children, after }: DetailLayoutProps) {
  return (
    <section aria-label={label} className="@container/detail min-w-0 flex-1 bg-background">
      <article className={GRID}>
        {head && <header className={MAIN}>{head}</header>}
        <header className={MAIN}><DetailTitle>{title}</DetailTitle></header>
        {sections.length > 0 && <DetailProperties sections={sections} />}
        <div className={cn(MAIN, "flex flex-col gap-5")}>
          <section aria-label="본문" className="flex min-w-0 flex-col gap-5">{children}</section>
          {after}
        </div>
      </article>
    </section>
  )
}

import { useId, useState, type FormEvent, type KeyboardEvent, type ReactNode } from "react"
import { cn } from "@/shared/lib/utils"
import { PersonAvatar } from "@/shared/ui/person-avatar"
import { ArrowUpIcon, type Icon } from "@/shared/ui/icon"
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupTextarea } from "@/shared/ui/input-group"

/** 활동의 한 칸: 일어난 일(누가 한 뒤의 한 문장과 그 종류의 아이콘) 또는 댓글. */
export type ActivityItem = { id: string; at: string; actorName: string } & (
  | { kind: "event"; text: string; icon: Icon }
  | { kind: "comment"; body: string }
)

const when = new Intl.DateTimeFormat("ko-KR", { month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit" })

function Time({ at }: { at: string }) {
  const date = new Date(at)
  return <time dateTime={at} title={date.toLocaleString("ko-KR")} className="text-xs whitespace-nowrap text-muted-foreground">{when.format(date)}</time>
}

/** 행위자 그림(20px): 이름 첫 글자(기본 그림은 제품이 PersonAvatar의 picture로 정한다). */
function ActorAvatar({ name }: { name: string }) {
  return <PersonAvatar name={name} />
}

/*
 * 세로선 하나(호호코워크 activity.module.css): 선은 댓글 카드 아바타의 가운데(카드 테두리 1px + 안쪽 12px + 아바타 반 10px = 23px)를 지난다.
 * 칸마다 자기 몫의 선을 위(::before) · 아래(::after) 두 토막으로 그려 표식 둘레를 비우고, 첫 칸 위와 끝 칸 아래는 그리지 않는다.
 */
const RAIL = "relative before:absolute before:top-0 before:left-[calc(1.4375rem-0.5px)] before:w-px before:bg-input after:absolute after:bottom-0 after:left-[calc(1.4375rem-0.5px)] after:w-px after:bg-input first:before:hidden last:after:hidden"

/** 변경: 선 위의 16px 아이콘, 아바타와 13px 한 문장(이름은 진한 글자), 때. */
function EventLine({ item }: { item: Extract<ActivityItem, { kind: "event" }> }) {
  return (
    <li className={cn(RAIL, "grid grid-cols-[1.25rem_minmax(0,1fr)] items-start gap-x-3 py-1 pl-3.25 before:h-1 after:top-6")}>
      <span aria-hidden className="grid size-5 place-items-center text-icon-muted"><item.icon /></span>
      <p className="flex min-w-0 items-start gap-2 text-sm/5 text-muted-foreground max-md:leading-normal">
        <ActorAvatar name={item.actorName} />
        <span className="min-w-0 break-keep wrap-anywhere">
          <span className="font-medium text-foreground">{item.actorName}</span> {item.text} · <Time at={item.at} />
        </span>
      </p>
    </li>
  )
}

/** 댓글: 선을 덮는 카드(테두리 · 12px 초타원): 아바타 · 이름 · 때, 그 아래 이름 줄에 맞춰 들여 쓴 글. */
function CommentCard({ item }: { item: Extract<ActivityItem, { kind: "comment" }> }) {
  return (
    <li className={cn(RAIL, "py-2 before:h-2 after:top-2")}>
      <article aria-label={`${item.actorName}의 댓글`} className="relative z-1 squircle rounded-xl border bg-card">
        <header className="flex min-h-10 items-center gap-2 pt-2 pr-2 pl-3 text-sm">
          <ActorAvatar name={item.actorName} />
          <span className="font-medium">{item.actorName}</span>
          <Time at={item.at} />
        </header>
        <p className="pt-1 pr-4 pb-4 pl-10 text-[0.875rem]/normal whitespace-pre-wrap wrap-anywhere max-md:text-base">{item.body}</p>
      </article>
    </li>
  )
}

/**
 * 댓글 입력(호호코워크 ChatComposer): 둥근 칸 안의 글 칸과 동그란 보내기. Enter는 보내기, Shift+Enter는 줄바꿈.
 * 보내는 동안 글은 남아 있다가 저장되면 비운다.
 */
export function CommentComposer({ label = "댓글", placeholder = "의견을 남겨 주세요", onSend }: {
  label?: string; placeholder?: string; onSend: (body: string) => Promise<unknown>
}) {
  const [text, setText] = useState("")
  const [isBusy, setBusy] = useState(false)
  const body = text.trim()
  const send = (event?: FormEvent) => {
    event?.preventDefault()
    if (!body || isBusy) return
    setBusy(true)
    onSend(body).then(() => setText(""), () => undefined).finally(() => setBusy(false))
  }
  const sendOnEnter = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key !== "Enter" || event.shiftKey || event.nativeEvent.isComposing) return
    event.preventDefault()
    send()
  }
  return (
    <form onSubmit={send}>
      <InputGroup className="squircle rounded-[0.875rem] bg-card">
        <InputGroupTextarea aria-label={label} placeholder={placeholder} rows={1} value={text} disabled={isBusy}
          onChange={event => setText(event.target.value)} onKeyDown={sendOnEnter} className="max-h-60 min-h-10 py-2.5" />
        <InputGroupAddon align="inline-end" className="self-end">
          <InputGroupButton type="submit" variant="default" size="icon-sm" aria-label="보내기" disabled={!body || isBusy} className="rounded-full">
            <ArrowUpIcon />
          </InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
    </form>
  )
}

/**
 * 활동(호호코워크 ActivityFeed): 변경 기록과 댓글을 오래된 것부터 세로선 하나에 잇고, 끝에 댓글 입력을 둔다.
 * 변경은 선 위의 아이콘과 한 문장, 댓글은 선을 덮는 카드다. onComment가 없으면 읽기만 한다.
 */
export function ActivityFeed({ items, onComment, empty }: {
  items: ActivityItem[]
  onComment?: (body: string) => Promise<unknown>
  /** 기록이 없을 때 그 자리에 보일 것(읽는 중의 자리 등). */
  empty?: ReactNode
}) {
  const titleId = useId()
  return (
    <section aria-labelledby={titleId} className="flex flex-col gap-3 pt-5">
      <h2 id={titleId} className="text-xs font-medium text-muted-foreground">활동</h2>
      {items.length > 0 ? (
        <ol aria-label="활동 기록" className="flex flex-col">
          {items.map(item => item.kind === "comment" ? <CommentCard key={item.id} item={item} /> : <EventLine key={item.id} item={item} />)}
        </ol>
      ) : empty}
      {onComment && <CommentComposer onSend={onComment} />}
    </section>
  )
}
